-- The German course (Tannenau) and the Swedish course grown to A2 (Lilla Ö),
-- with each concept's unit and level. Generated by `npm run content:sql -- de sv`.

-- de: 953 concepts, in course order.
on conflict (language_code, slug) do update
set
  kind = excluded.kind,
  canonical_form = excluded.canonical_form,
  gloss = excluded.gloss,
  description = coalesce(nullif(excluded.description, excluded.gloss), public.concepts.description, excluded.description),
  metadata = public.concepts.metadata || excluded.metadata,
  sort_order = excluded.sort_order,
  is_active = true,
  updated_at = now();

-- sv: 685 concepts, in course order.
on conflict (language_code, slug) do update
set
  kind = excluded.kind,
  canonical_form = excluded.canonical_form,
  gloss = excluded.gloss,
  description = coalesce(nullif(excluded.description, excluded.gloss), public.concepts.description, excluded.description),
  metadata = public.concepts.metadata || excluded.metadata,
  sort_order = excluded.sort_order,
  is_active = true,
  updated_at = now();
